import React, { useState, useEffect } from 'react';

// Custom hook untuk localStorage
function useLocalStorage(key, initialValue) {
    const [value, setValue] = useState(() => {
        try {
            const stored = localStorage.getItem(key);
            return stored ? JSON.parse(stored) : initialValue;
        } catch {
            return initialValue;
        }
    });

    useEffect(() => {
        localStorage.setItem(key, JSON.stringify(value));
    }, [key, value]);

    return [value, setValue];
}

export default function CatatanApp() {
    const [catatan, setCatatan] = useLocalStorage('catatan', []);
    const [text, setText] = useState('');

    const tambah = () => {
        if (!text.trim()) return;
        setCatatan([
            ...catatan,
            { id: Date.now(), isi: text.trim(), waktu: new Date().toLocaleString() }
        ]);
        setText('');
    };

    const hapus = (id) => {
        setCatatan(catatan.filter(c => c.id !== id));
    };

    return (
        <div className="catatan-app">
            <h2>Catatan Saya</h2>
            <div className="input-row">
                <input
                    value={text}
                    onChange={(e) => setText(e.target.value)}
                    placeholder="Tulis catatan..."
                    onKeyPress={(e) => e.key === 'Enter' && tambah()}
                />
                <button onClick={tambah}>Tambah</button>
            </div>
            <ul>
                {catatan.map(c => (
                    <li key={c.id}>
                        <p>{c.isi}</p>
                        <small>{c.waktu}</small>
                        <button onClick={() => hapus(c.id)}>Hapus</button>
                    </li>
                ))}
            </ul>
        </div>
    );
}

import React, { useState, useEffect } from 'react';
import {
  View, Text, FlatList, ActivityIndicator,
  TouchableOpacity, StyleSheet, Image, RefreshControl,
} from 'react-native';

export default function ProductList({ navigation }) {
  const [produk, setProduk] = useState([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState(null);

  const fetchData = async () => {
    try {
      const res = await fetch('https://api.contoh.com/produk');
      const data = await res.json();
      setProduk(data);
      setError(null);
    } catch (err) {
      setError('Gagal memuat data');
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const onRefresh = () => {
    setRefreshing(true);
    fetchData();
  };

  const renderItem = ({ item }) => (
    <TouchableOpacity
      style={styles.card}
      onPress={() => navigation.navigate('Detail', { id: item.id })}
    >
      <Image
        source={{ uri: item.gambar }}
        style={styles.image}
        resizeMode="cover"
      />
      <View style={styles.cardBody}>
        <Text style={styles.nama}>{item.nama}</Text>
        <Text style={styles.harga}>
          Rp {Number(item.harga).toLocaleString('id-ID')}
        </Text>
        <Text style={styles.stok} numberOfLines={1}>
          Stok: {item.stok}
        </Text>
      </View>
    </TouchableOpacity>
  );

  if (loading) {
    return (
      <View style={styles.center}>
        <ActivityIndicator size="large" color="#2563eb" />
      </View>
    );
  }

  if (error) {
    return (
      <View style={styles.center}>
        <Text style={styles.error}>{error}</Text>
        <TouchableOpacity onPress={fetchData} style={styles.retry}>
          <Text style={styles.retryText}>Coba Lagi</Text>
        </TouchableOpacity>
      </View>
    );
  }

  return (
    <FlatList
      data={produk}
      keyExtractor={(item) => String(item.id)}
      renderItem={renderItem}
      contentContainerStyle={styles.list}
      refreshControl={
        <RefreshControl refreshing={refreshing} onRefresh={onRefresh} />
      }
      ListEmptyComponent={
        <Text style={styles.empty}>Belum ada produk</Text>
      }
    />
  );
}

